/// <summary>
///     Extension of formControl <c>AVAPurchRemainPercentageFilter</c> in form <c>PurchLineOpenOrder</c>
/// </summary>
[ExtensionOf(formControlStr(PurchLineOpenOrder, AVAPurchRemainPercentageFilter))]
final class AVAPurchLineOpenOrderFrm_AVAPurchRemainPercentageFilter_Extension
{
}

Method.Source:
/// <summary>
///     AVA <c>modified</c> method.
///     AVA - Schneider 06.05.2024
/// </summary>
/// <returns>
///     <c>boolean</c> as return value
/// </returns>
public boolean modified()
{
    boolean retVal;

    FormDataSource purchLineLoc;

    retVal = next modified();

    purchLineLoc = element.purchLine_ds;

    purchLineLoc.executeQuery();

    return retVal;
}

/// <summary>
///     AVA <c>validate</c> method.
///     AVA - Schneider 06.05.2024
/// </summary>
/// <returns>
///     <c>boolean</c> as return value
/// </returns>
public boolean validate()
{
    boolean retVal; 

    retVal = next validate();

    if(     this.realValue() > 100.0
        ||  this.realValue() < 0.0  )
    {
        retVal = false;

        Error("@NDX:NXAPurchRemainPercentValidate");
    }
    return retVal;
}
